<?php
if($type==='threshold_template'){$rows=[['Master SKU','Product Description','Brand','Category','Low Stock Threshold']];foreach(product_options() as $p)$rows[]=[$p['master_sku'],$p['name'],$p['brand'],$p['category'],$p['low_stock_threshold']];csv_download('RS8_Product_Thresholds.csv',$rows);}
if($type==='threshold_errors'){$q=$pdo->prepare('SELECT * FROM threshold_batches WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$b=$q->fetch();if(!$b)exit('Batch not found.');$rows=[['RS8 Threshold Validation Error Report'],['Batch',$b['batch_ref']],['File',$b['filename']],[],['No.','Details','Required Action']];foreach(json_decode($b['error_json']??'[]',true)?:[] as $i=>$error)$rows[]=[$i+1,$error,'Correct the source row and upload again.'];csv_download('RS8_Threshold_Errors_'.$b['id'].'.csv',$rows);}
if($type==='original_preview'){
 $q=$pdo->prepare('SELECT id,stored_path,filename,platform,created_at FROM import_batches WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$r=$q->fetch();$path=$r?realpath(__DIR__.'/'.$r['stored_path']):false;
 if(!$path||!is_file($path))exit('Original upload not found.');$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));if($ext==='pdf'){header('Content-Type: application/pdf');readfile($path);exit;}
 if($ext!=='xlsx')exit('A preview is unavailable for this format. Download the original upload.');require_once __DIR__.'/pdf_preview.php';stream_workbook_preview($r['filename'],workbook_preview_data($path),['batch_id'=>$r['id'],'platform'=>$r['platform'],'uploaded_at'=>$r['created_at']]);
}
if($type==='outflow_print'){
 $id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT b.*,u.name user_name FROM import_batches b LEFT JOIN users u ON u.id=b.user_id WHERE b.id=?');$q->execute([$id]);$b=$q->fetch();if(!$b)exit('Batch not found.');
 $q=$pdo->prepare('SELECT p.master_sku,p.name,SUM(o.qty) qty FROM outflows o JOIN products p ON p.id=o.product_id WHERE o.import_batch_id=? GROUP BY p.id,p.master_sku,p.name ORDER BY p.name');$q->execute([$id]);$rows=$q->fetchAll();$total=array_sum(array_column($rows,'qty'));
 receipt_header('Outflow Batch Summary','#'.str_pad((string)$id,6,'0',STR_PAD_LEFT));echo '<div class="meta"><div><b>Date:</b> '.e($b['created_at']).'</div><div><b>Platform:</b> '.platform_label($b['platform']).'</div><div><b>Original File:</b> '.e($b['filename']).'</div><div><b>Processed By:</b> '.e($b['user_name']).'</div><div><b>Status:</b> '.e($b['status']).'</div><div><b>Posted Units:</b> '.$total.' pcs</div></div><table><thead><tr><th>Master SKU</th><th>Product Description</th><th>Qty Out</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['master_sku']).'</td><td>'.e($r['name']).'</td><td>'.(int)$r['qty'].' pcs</td></tr>';echo '<tr><td colspan="2"><b>TOTAL POSTED</b></td><td><b>'.$total.' pcs</b></td></tr></tbody></table><p style="font-size:11px">Uploaded units: '.(int)$b['units'].'; unmapped rows: '.(int)$b['unmapped_count'].'; duplicates: '.(int)$b['duplicate_count'].'; errors: '.(int)$b['error_count'].'. Only posted stock is included in the summary.</p>';receipt_footer();exit;
}
